struct step { const char *id; int (*run)(struct msg *); };
struct msg { const struct step *slip; size_t slip_len, cursor; };

int advance(struct msg *m) {
    while (m->cursor < m->slip_len) {
        if (m->slip[m->cursor].run(m) != 0) return -1;  /* caller retries or undoes */
        m->cursor++;
    }
    return 0;
}
